 screens.search=()=>{const q=A.params.get('q')?.trim()||'',needle=q.toLowerCase(),rows=[];const add=(terms,title,context,to)=>{if(q&&terms.toLowerCase().includes(needle)&&A.isAllowed(to.split('?')[0]))rows.push([esc(title),esc(context),link(to,'Open original record')]);};for(const o of S.state.orders){const c=S.state.customers.find(c=>c.id===o.customer);add([o.id,c.name,o.paymentRef,...o.items.map(i=>i.title)].join(' '),o.id,c.name+' · '+S.summary(o),'orders/record?id='+o.id);for(const i of o.items){const p=i.parcel;add([p?.id,p?.awb,p?.shiprocketOrder,p?.shiprocketShipment].filter(Boolean).join(' '),p?.id||'',i.title,'orders/parcel?id='+o.id+'&item='+i.id);}}for(const c of S.state.customers)add([c.id,c.name,c.email,c.phone].join(' '),c.name,c.id,'customers/profile?id='+c.id);for(const p of S.state.products)add([p.id,p.title,p.slug].join(' '),p.title,p.id+' · '+p.status,'products/artwork?id='+p.id);for(const c of S.state.cases)add([c.id,c.subject,c.order].join(' '),c.id,c.subject,'support/case?id='+c.id);return heading('Search records',q?'Results for “'+q+'”':'Find an order, customer, artwork or provider reference.',rows.length?table('Original record results',['Record','Context','Open'],rows):empty(q?'No matching records':'Start with a name or reference','Try Meera, AS-1003, Lantern or AWB-DEMO-1003-1.'));};
 const reportOrders=()=>S.state.orders.filter(o=>o.payment==='Captured'&&!o.replacement&&(o.paidDate||o.created)>=(A.params.get('from')||'2026-09-01')&&(o.paidDate||o.created)<=(A.params.get('to')||'2026-09-30'));
 function totals(rows){const collected=rows.reduce((a,o)=>a+o.total,0),refunds=rows.reduce((a,o)=>a+completed(o),0),costs=rows.flatMap(o=>Object.values(o.costs)),replacementCosts=S.state.orders.filter(o=>o.replacement&&rows.some(p=>p.id===o.parent)).flatMap(o=>Object.values(o.costs)),allCosts=[...costs,...replacementCosts];return {collected,refunds,bank:rows.filter(o=>o.bankMatched).reduce((a,o)=>a+o.bankAmount,0),settled:rows.some(o=>o.settlement==='Provider settled'&&expectedBank(o)===null)?null:rows.filter(o=>o.settlement==='Provider settled').reduce((a,o)=>a+expectedBank(o),0),contribution:allCosts.some(x=>x===null)?null:collected-refunds-allCosts.reduce((a,x)=>a+x,0)};}
 screens.reports=()=>screens['reports/sales']();
 screens['reports/sales']=()=>{const orders=reportOrders(),t=totals(orders);return heading('Sales & money','Reconcile the source records before making a decision.',form('report-filter',`<div class="filter-form">${field('from','From date',A.params.get('from')||'2026-09-01','date')}${field('to','To date',A.params.get('to')||'2026-09-30','date')}</div>`,'Apply reporting dates')+`<div class="stats">${stat('Captured collection',money(t.collected),orders.length+' paid purchases')}${stat('Confirmed refunds',money(t.refunds),'Completed provider outcomes')}${stat('Provider settled',money(t.settled),'Distinct from bank matching')}${stat('Bank matched',money(t.bank),'Verified sample receipts')}</div>`+notice('Recorded contribution: '+(t.contribution===null?'incomplete':money(t.contribution)),t.contribution===null?'Some shipping or remedy costs are unknown. They remain unknown; the report does not turn them into zero or claim net profit.':'This is contribution after recorded costs, not net business profit. Cost estimates remain marked as estimates.',t.contribution===null?'warn':'')+table('Every total has a source',['Order','Collected','Refunded','Production / pack','Shipping / fee / remedy','Cost basis','Review'],orders.map(o=>[link('orders/record?id='+o.id,o.id),money(o.total),money(completed(o)),money(o.costs.production)+' / '+money(o.costs.packaging),money(o.costs.shipping)+' / '+money(o.costs.fees)+' / '+money(o.costs.remedy),pill(o.costBasis,'neutral'),link('orders/settlement?id='+o.id,'Review costs and settlement')]))+panel('Metric definitions',list(['Date filter: captured-payment cohort (sample purchase and capture dates are 13 September 2026); refunds and settlement status are cumulative for those orders.','Collected = captured purchase amounts. Only confirmed completed refunds count as refunded. Outstanding submissions remain committed separately.','Provider settled = sample net settlement after confirmed refunds and recorded fees. Bank matched requires a matching receipt.','Internal calculations use integer paise. Display and exports retain INR; percentage rounding is only for presentation. Tax classification is unconfigured, with no net-of-tax profit claim.','Replacement orders are excluded from new sales; their recorded costs belong to the original purchase. Unknown and estimated costs remain labelled.']))+actions(button('export','Download finance CSV',{kind:'finance'},'button secondary'),link('orders/settlements','Review unmatched settlements','button secondary')));};
