 handlers.costs=({id})=>{S.guard('finance');const o=S.order(id);modal('Record order costs','Unknown values stay blank. Estimated contribution is not net business profit.',Object.entries(o.costs).map(([k,v])=>field(k,k+' cost (INR)',v===null?'':v/100,'number','Leave blank if unknown.',false)).join('')+select('basis','Cost basis',['Estimated','Actual','Mixed / incomplete'],o.costBasis)+textarea('reason','Evidence or estimate reference'),d=>S.mutate(id,'Record fulfilment costs',()=>{for(const k of Object.keys(o.costs)){const n=d[k]===''?null:Math.round(Number(d[k])*100);if(n!==null&&(!Number.isSafeInteger(n)||n<0))throw Error('Costs must be non-negative amounts, or blank when unknown.');o.costs[k]=n;}o.costBasis=d.basis;o.costEvidence=d.reason;},d.reason),'Save recorded costs');};
 screens['reports/performance']=()=>{const orders=reportOrders(),groups=new Map();for(const o of orders)for(const i of o.items){const p=S.state.products.find(p=>p.id===i.artId),key=i.artId+' / '+i.frame;if(!groups.has(key))groups.set(key,{id:i.artId,title:i.title,frame:i.frame,collection:p?.collection,qty:0,collected:0,refunds:0});const g=groups.get(key);g.qty+=i.qty;g.collected+=i.qty*i.price;g.refunds+=o.refunds.filter(r=>r.item===i.id&&r.status==='Completed').reduce((a,r)=>a+r.amount,0);}return heading('Artwork performance','Sales by artwork, collection and frame, with replacement sales excluded.',table('Artwork / collection / finish',['Artwork','Collection','Frame','Sold quantity','Collected','Refunded'],[...groups.values()].map(g=>[link('products/artwork?id='+g.id,g.title),esc(g.collection),esc(g.frame),g.qty,money(g.collected),money(g.refunds)]))+notice('Read this alongside costs','These are captured line values for the September sample cohort. A popular artwork is not automatically the most profitable. '+link('reports/sales','Review cost completeness')));};
 screens['reports/operations']=()=>{const s=S.state,orders=s.orders.filter(o=>!o.replacement&&!o.cancelled),items=orders.flatMap(o=>o.items),late=orders.filter(o=>o.originalDue<'2026-09-13'&&o.items.some(i=>i.stage<10)),delivered=items.filter(i=>i.stage===10).length,claims=s.cases.filter(c=>c.claim).length,rto=items.filter(i=>i.parcel?.status==='Returning to studio').length,reopened=s.cases.filter(c=>c.status==='Reopened').length;return heading('Operations','A useful weekly view of late work, customer care and recurring problems.',`<div class="stats">${stat('Late open orders',late.length,orders.length+' non-cancelled purchases')}${stat('Delivered items',delivered,items.length+' purchased items')}${stat('Damage cases',claims,delivered+' delivered items in sample')}${stat('Reopened requests',reopened,s.cases.length+' total cases')}</div>`+table('Work behind the original promise',['Order','Original promise','Current promise','Owner','Next step'],late.map(o=>[link('orders/record?id='+o.id,o.id),o.originalDue,o.due,esc(o.owner),link('orders/job?id='+o.id,'Review studio job')]))+panel('Customer care & delivery',facts([['Open cases',s.cases.filter(c=>c.status!=='Resolved').length+' / '+s.cases.length+' total'],['First response recorded',s.cases.filter(c=>c.firstResponseAt).length+' / '+s.cases.length+' captured cases'],['Return-to-origin parcels',rto+' / '+items.filter(i=>i.parcel).length+' recorded parcels'],['Message failures',s.messages.filter(m=>['Failed','Unknown'].includes(m.status)).length+' / '+s.messages.length+' messages'],['Promise treatment','Original dates remain the performance baseline; revised dates are shown separately']]))+actions(button('weekly-digest','Preview weekly digest'),link('settings/system','Review service failures','button secondary')));};
