 screens.tools=()=>heading('Tools, when the studio is ready','Three planned applications after V1. Their scope and build order remain on hold.',`<div class="cards">${[['Accounting','Documents, bank matching and recorded costs','orders/settlements','Orders retains the purchase facts and executes payment/refund operations.'],['CRM','Customer history and channel preferences','customers','Future CRM reuses original identities and consent records.'],['Customer Support','Requests, saved replies, claims and returns','support','The future tool reuses case history; authorised Orders actions own remedies.']].map(([title,bridge,to,note])=>`<section class="card planned"><p class="card-number">AF1 / AFTER V1</p>${pill('Planned · on hold','neutral')}<h2>${title}</h2><p>${note}</p>${link(to,'V1: '+bridge)}</section>`).join('')}</div>`+panel('Shared records for later reuse',facts([['Order / customer / artwork','AS-*, C-*, ART-* stable sample identities'],['Jobs and parcels','Order + line-item relationship; no duplicate fulfilment owner'],['Cases / remedies','CS-* and RF-* link to the original order'],['Exports','CSV rows include original IDs and money in integer paise'],['Future tools','No new login, subscription, database or speculative platform is required now']])));
