 screens['settings/access']=()=>heading('Staff & access','Preview least-privilege roles and access recovery.',notice('Access demonstration','The role selector changes the local UI experience. It is not real login or server security. Direct actions, private files and sessions must be enforced on the server in the live build.')+table('Staff role preview',['Person','Daily work','Sensitive boundaries','Session'],[['Khalid · Owner','All V1 areas; finance role held by owner','Approves finance, access and publication',pill(S.state.role==='owner'?'Current preview':'Available','neutral')],['Asha · Operations','Jobs, inspection, packing, parcels and catalogue work','Finance, customer exports and owner settings restricted',pill(S.state.revoked.includes('operations')?'Revoked in demo':'Available','neutral')],['Rahul · Support','Cases, customer history and remedy recommendations','No provider refunds, finance exports or access changes',pill(S.state.revoked.includes('support')?'Revoked in demo':'Available','neutral')]])+actions(button('session-signout','Preview sign-out',{},'button secondary'),S.state.role==='owner'?button('staff-revoke','Review access revocation',{},'button secondary'):'',link('settings/recovery','Owner recovery preview')));
