 screens['settings/activity']=()=>heading('Activity history','The actor, reason and previous values stay with consequential actions.',S.state.audit.length?table('Recorded local activity',['Time / actor','Record / action','Reason','Previous / next values'],S.state.audit.map(a=>[esc(new Date(a.at).toLocaleString('en-IN'))+`<small>${esc(a.actor)} · ${esc(a.source)}</small>`,esc(a.entity)+`<small>${esc(a.action)}</small>`,esc(a.reason),details('Inspect event',`<pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${esc(JSON.stringify({before:a.before,after:a.after},null,2))}</pre>`)])):empty('No local actions yet','Use the order journey or edit a sample record. Its activity will appear here.','orders','Open Today'));
