 handlers['automation-replay']=()=>{S.guard('settings');const rows=S.state.messages.filter(m=>m.status==='Queued');modal('Replay safe queued follow-ups?','Only never-submitted queued messages are eligible. Failed and unknown sends require their own verification.',rows.length?list(rows.map(m=>esc(m.kind)+' · '+esc(m.order)+' / '+esc(m.item))):notice('No eligible queued work','Nothing will be resubmitted.'),()=>S.mutate('AUTOMATION','Replay known-safe queued messages',()=>{if(S.state.paused)throw Error('Review and resume the paused rules before replay.');S.state.messages.filter(m=>m.status==='Queued').forEach(m=>{m.status='Provider accepted';m.attempts=1;});}),'Replay eligible work');};
 screens['settings/system']=()=>heading('System checks','Own the incident, preserve work and verify the recovery.',panel('Current sample incident',facts([['Owner',esc(S.state.incident.owner)],['State',pill(S.state.incident.status,'warn')],['Next action',esc(S.state.incident.note)],['Automation',S.state.paused?'Paused':'Running sample follow-ups']])+actions(button('incident','Manage incident',{},'button secondary'),button('automation-pause',S.state.paused?'Review resuming automation':'Emergency automation pause')))+table('Operating checks',['Area','Sample result','Next step'],[['Order intake / pending work','Original references retained',link('orders/payments','Check unresolved payment')],['Shipping / tracking','Unknown and stale outcomes stay visible',link('orders/shipping','Review parcels')],['Transactional email','Failed sends require an owner',link('support/messages','Review message outcomes')],['Private storage / backups','Live verification not performed',link('settings/recovery','Recovery rehearsal')],['Availability / load','No live performance or uptime measurements',link('settings/readiness','Review required evidence')]])+panel('Recovery sequence',list(['Name the incident owner and pause affected follow-ups.','Preserve known payment, shipping and messaging references.','Restore a tested backup of durable records and evidence in a separate test environment.','Reconcile recent provider outcomes before replaying known-safe pending work.','Measure restore time, permitted data loss, migrations/rollback and representative peak workload.'])));
